const dateOnly=date=>new Intl.DateTimeFormat(getLocale()==='ms'?'ms-MY':'en-MY',{month:'short',day:'numeric',year:'numeric',timeZone:'Asia/Kuala_Lumpur'}).format(new Date(date));
