function localDateTime(){const n=new Date(),adjusted=new Date(n.getTime()-n.getTimezoneOffset()*60000);return adjusted.toISOString().slice(0,16);}
function getDraft(){if(!reportDraft)reportDraft=loadDraft()||freshDraft();return reportDraft;}
function saveCurrentDraft(){saveDraft(getDraft());}
function showToast(message,isError=false){let el=$('.toast');if(el)el.remove();el=document.createElement('div');el.className='toast'+(isError?' error':'');el.textContent=translateText(message);document.body.appendChild(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),4500);}
function go(path){const h=href(path);if(location.hash===h){render();window.scrollTo({top:0,behavior:'instant'});}else location.hash=h;}
const active=(prefix)=>pathNow().pathname.startsWith(prefix)?'active':'';
function header(){const r=getRole(),nav=[['/','Home'],['/report','Report'],['/track','Track case'],['/insights','Insights'],['/review','Review'],['/response','Response'],['/demo','Demo']];return `<header class="site-header premium-header"><div class="container header-inner"><a class="logo" href="#/" aria-label="PenyuGuard home"><span class="logo-symbol">${icon('turtle',25)}</span><span>Penyu<span class="brand-accent">Guard</span><small>MARINE CONSERVATION TECH</small></span></a><nav class="nav-links" aria-label="Main navigation">${nav.map(([p,t])=>`<a href="${href(p)}" class="${p==='/'?(pathNow().pathname==='/'?'active':''):active(p)}">${t}</a>`).join('')}</nav><div class="header-actions"><label class="language-control" for="language-select"><span class="language-icon" aria-hidden="true">${icon('globe',15)}</span><span class="language-copy">Language / Bahasa</span><select id="language-select" class="language-select" aria-label="Language / Bahasa"><option value="en" ${getLocale()==='en'?'selected':''}>EN</option><option value="ms" ${getLocale()==='ms'?'selected':''}>BM</option></select></label><select id="role-select" class="role-select" title="Demo role switcher, not secure authentication" aria-label="Choose demo role"><option value="reporter" ${r==='reporter'?'selected':''}>Reporter · Demo</option><option value="reviewer" ${r==='reviewer'?'selected':''}>Reviewer · Demo</option><option value="coordinator" ${r==='coordinator'?'selected':''}>Coordinator · Demo</option></select><a href="#/report" class="btn header-cta">${icon('plus',16)} New report</a></div><button class="mobile-menu" data-action="mobile-menu" aria-label="Toggle menu" aria-expanded="${menuOpen}">${icon(menuOpen?'x':'menu',24)}</button></div>${menuOpen?`<nav class="mobile-nav" aria-label="Mobile navigation">${nav.map(([p,t])=>`<a href="${href(p)}">${t}</a>`).join('')}<label class="language-control language-control-mobile" for="language-mobile"><span class="language-icon" aria-hidden="true">${icon('globe',15)}</span><span class="language-copy">Language / Bahasa</span><select id="language-mobile" class="language-select" aria-label="Language / Bahasa"><option value="en" ${getLocale()==='en'?'selected':''}>English</option><option value="ms" ${getLocale()==='ms'?'selected':''}>Bahasa Melayu</option></select></label><select id="role-mobile" class="role-select" aria-label="Demo role"><option value="reporter" ${r==='reporter'?'selected':''}>Reporter · Demo</option><option value="reviewer" ${r==='reviewer'?'selected':''}>Reviewer · Demo</option><option value="coordinator" ${r==='coordinator'?'selected':''}>Coordinator · Demo</option></select></nav>`:''}</header><div class="demo-strip"><div class="container"><span>${icon('info',14)} ACADEMIC DEMONSTRATION <span class="strip-sep">/</span> CASES ARE FICTIONAL</span><span>Viewing as <b>${esc(r.charAt(0).toUpperCase()+r.slice(1))}</b> · Demo access only</span></div></div>`;}
function footer(){return `<footer class="site-footer no-print"><div class="container"><div class="footer-grid"><div><a href="#/" class="logo logo-light"><span class="logo-symbol">${icon('turtle',24)}</span><span>PenyuGuard<small>MARINE CONSERVATION TECH</small></span></a><p>Protect Every Turtle. Connect Every Rescue. An academic concept exploring safer reporting, thoughtful conservation review and transparent case histories.</p><span class="footer-location">${icon('pin',16)} Pulau Perhentian, Terengganu, Malaysia</span></div><div><h4>Platform</h4><div class="footer-links"><a href="#/report">Report a concern</a><a href="#/track">Track a passport</a><a href="#/insights">Case insights</a><a href="#/demo">Guided demonstration</a></div></div><div><h4>Context & credits</h4><div class="footer-links"><a href="https://www.perhentianturtleproject.org/" target="_blank" rel="noopener noreferrer">Perhentian Turtle Project ↗</a><a href="https://www.dof.gov.my/" target="_blank" rel="noopener noreferrer">Department of Fisheries Malaysia ↗</a><a href="https://commons.wikimedia.org/wiki/File:Green-sea-turtle.jpg" target="_blank" rel="noopener noreferrer">Turtle photography references ↗</a><a href="https://commons.wikimedia.org/wiki/File:Perhentian_Islands,_Malaysia,_Beach.jpg" target="_blank" rel="noopener noreferrer">Island photo: Vyacheslav Argenberg ↗</a><a href="https://commons.wikimedia.org/wiki/File:Underwater_photo_of_coral_reef.jpg" target="_blank" rel="noopener noreferrer">Reef photo: Jerry Reid / USFWS ↗</a></div></div></div><div class="footer-bottom"><strong>Demonstration prototype.</strong> ${disclaimer}<div class="footer-legal">© ${new Date().getFullYear()} PenyuGuard · Unaffiliated with listed conservation organizations · Photography is illustrative and not part of the fictional case records.</div></div></div></footer>`;}
function introLine(label,heading,paragraph){return `<div class="page-head premium-page-head"><div><div class="label-line">${label}</div><h1 class="page-title">${heading}</h1><p class="page-lead">${paragraph}</p></div><span class="page-head-ornament" aria-hidden="true">${icon('waves',35)}</span></div>`;}
