  <div class="cinema-gallery-grid">
   <a class="cinema-gallery-card tall" href="#/report">${photo('gallery2','cinema-gallery-img')}<span class="cinema-gallery-shade"></span><span class="cinema-gallery-index">01 / LIFE</span><span class="cinema-gallery-caption"><strong>Witness the wonder.</strong><small>Make a responsible observation ↗</small></span></a>
   <a class="cinema-gallery-card stagger" href="#/track">${photo('gallery3','cinema-gallery-img')}<span class="cinema-gallery-shade"></span><span class="cinema-gallery-index">02 / HABITAT</span><span class="cinema-gallery-caption"><strong>Every detail matters.</strong><small>Explore tracked observations ↗</small></span></a>
   <a class="cinema-gallery-card tall" href="#/insights">${photo('gallery4','cinema-gallery-img')}<span class="cinema-gallery-shade"></span><span class="cinema-gallery-index">03 / PLACE</span><span class="cinema-gallery-caption"><strong>Protect the places.</strong><small>View illustrative area insights ↗</small></span></a>
  </div>
